/// A colour written as 8-bit sRGB, in Rune's linear space.
pub fn srgb(hex: u32) -> Color {
    let c = |v: u32| {
        let v = (v & 0xff) as f32 / 255.0;
        if v <= 0.040_45 { v / 12.92 } else { ((v + 0.055) / 1.055).powf(2.4) }
    };
    Color { r: c(hex >> 16), g: c(hex >> 8), b: c(hex), a: 1.0 }
}

/// A logo and the colour to draw it in: its brand colour, or None for the
/// theme's icon colour (single-colour marks) or its own colours (Pi, Slack).
pub type Mark = (&'static Icon, Option<Color>);

pub fn agent(id: &str) -> Option<Mark> {
    Some(match id {
        "opencode" => (provider_icons::named("opencode")?, None),
        "claude" => (provider_icons::named("claude-agent")?, Some(srgb(0xD97757))),
        "codex" => (&CODEX, None),
        "cursor" => (&CURSOR, None),
        "pi" => (&PI, None),
        _ => return None,
    })
}

/// The place a report's `sends_to` names, by the first brand it mentions.
pub fn place(sends_to: &str) -> Option<Mark> {
    let s = sends_to.to_lowercase();
    let has = |w: &str| s.contains(w);
    Some(if has("notion") {
        (&NOTION, None)
    } else if has("slack") {
        (&SLACK, None)
    } else if has("linear") || has("issue") {
        (&LINEAR, Some(srgb(0x5E6AD2)))
    } else if has("jira") {
        (&JIRA, Some(srgb(0x2684FF)))
    } else if has("github") {
        (&oc::GITHUB, None)
    } else {
        return None;
    })
}

/// A place Hex Meetings posts to.
pub fn for_place(place: crate::places::Place) -> Mark {
    use crate::places::Place;
    match place {
        Place::Slack => (&SLACK, None),
        Place::Notion => (&NOTION, None),
        Place::GitHub => (&oc::GITHUB, None),
        Place::Linear => (&LINEAR, Some(srgb(0x5E6AD2))),
    }
}

pub fn markdown() -> Mark {
    (&MARKDOWN, None)
}

