/// The app a call happened in, as Hex names it. None for apps with no
/// openly licensed mark (Gather, Google Voice): they get [`CALL`].
pub fn call_app(name: &str) -> Option<Mark> {
    let s = name.to_lowercase();
    let brand = |icon: &'static Icon, hex: u32| (icon, Some(srgb(hex)));
    Some(match () {
        _ if s.contains("teams") => (&TEAMS, None),
        _ if s.contains("facetime") => brand(&FACETIME, 0x34C759),
        _ if s == "phone" => (&PHONE, None),
        _ if s.contains("zoom") => (&ZOOM_APP, None),
        _ if s.contains("google meet") || s == "meet" => brand(&GOOGLEMEET, 0x00897B),
        _ if s.contains("slack") => (&SLACK, None),
        _ if s.contains("whatsapp") => brand(&WHATSAPP, 0x25D366),
        _ if s.contains("discord") => brand(&DISCORD, 0x5865F2),
        _ if s.contains("signal") => brand(&SIGNAL, 0x3B45FD),
        _ if s.contains("telegram") => brand(&TELEGRAM, 0x26A5E4),
        _ if s.contains("wechat") => brand(&WECHAT, 0x07C160),
        _ if s == "line" => brand(&LINE, 0x00C300),
        _ if s.contains("webex") => (&WEBEX, None),
        _ if s.contains("element") => brand(&ELEMENT, 0x0DBD8B),
        _ if s.contains("messenger") => brand(&MESSENGER, 0x0866FF),
        _ if s.contains("groupme") => brand(&GROUPME, 0x00AFF0),
        _ => return None,
    })
}
